import{_ as l,b as t,c as e,g as a}from"./chunks/framework.86O3EbG5.js";const _=JSON.parse('{"title":"Essential Math for AI: Next‑Level Mathematics for Efficient and Successful AI Systems","description":"","frontmatter":{"title":"Essential Math for AI: Next‑Level Mathematics for Efficient and Successful AI Systems","subTitle":"AI 必备数学：构建高效、成功 AI 系统的高阶数学(ch03)","author":"oasis","date":"2026-08-24T00:00:00.000Z","tags":["AI","Math"]},"headers":[],"relativePath":"articles/artificial-intelligence/books/essential-math-for-ai/2.md","filePath":"articles/artificial-intelligence/books/essential-math-for-ai/2.md"}'),o={name:"articles/artificial-intelligence/books/essential-math-for-ai/2.md"};function s(n,i,c,r,d,f){return t(),e("div",null,[...i[0]||(i[0]=[a('<h2 id="fitting-functions-to-data" tabindex="-1">Fitting Functions to Data</h2><h3 id="人工智能机器学习的结构" tabindex="-1">人工智能机器学习的结构</h3><ol><li>定义问题</li><li>收集数据和处理</li><li>创建假设函数</li><li>确定权重的数值</li><li>创建错误函数（误差函数、成本函数、目标函数或损失函数）</li><li>确定数学公式</li><li>确定寻找最小值的方法</li><li>使用反向传播算法</li><li>对函数进行正则化，即使其更加平滑、振荡更小、更稳定</li></ol><h3 id="传统且重要的机器学习模型" tabindex="-1">传统且重要的机器学习模型</h3><ol><li>线性回归：预测一个数值</li><li>逻辑回归：分为两类</li><li>softmax 回归：分为多类</li><li>支持向量机：分为两类或进行回归（预测一个数值）</li><li>决策树：分为任意数量的类别或进行回归（预测一个数值）</li><li>随机森林：分为任意类别或进行回归（预测一个数值）</li><li>模型嵌入：通过平均预测值，将多个模型的结果绑定在一起</li><li>K均值聚类：分为任意数量的类型或进行回归</li></ol><h3 id="回归类模型的过程" tabindex="-1">回归类模型的过程</h3><ol><li>训练函数（training function）</li><li>损失函数（loss function）</li><li>优化（Opimization）</li></ol><h3 id="数值解和分析解" tabindex="-1">数值解和分析解</h3><p>数值解：</p><ol><li>比分析解更容易获得</li><li>数值解只是近似解，需要数学分析相关知识</li><li>需要足够的计算能力</li></ol><p>分析解</p><ol><li>解析不容易获得或有时无法获得</li><li>需要数学和领域专长</li><li>解析方法对于描述解的总要性质、知道数值技术以及近似值方法提供基准真值具有极高的价值。</li></ol><h3 id="回归的重要结构" tabindex="-1">回归的重要结构</h3><ol><li>训练函数：参数模型与现实模型之间的对比</li><li>损失函数：</li></ol><ul><li>预测值与真实值的对比</li><li>绝对值距离与平方距离的对比</li><li>具有奇点的函数</li><li>线性回归的损失函数是平方差</li><li>列向量</li><li>训练集、验证集和测试集</li><li>训练数据具有高度相关的特征</li></ul><ol start="3"><li>性能优化：</li></ol><ul><li>凸优化</li><li>定位函数的最小化值</li><li>微积分概述</li><li>一维优化</li><li>线性表达式的导数</li><li>最小化均方误差损失函数</li><li>矩阵乘向量</li><li>过拟合</li></ul><h4 id="训练函数" tabindex="-1">训练函数</h4>',18)])])}const u=l(o,[["render",s]]);export{_ as __pageData,u as default};
